import { DateTime } from "luxon";
import EntityV2 from "../abstract/entityV2";
import EntityValidationError from "../abstract/entityValidationError";
import MetadataKeysCollection from "../metadata/metadataKeysCollection";
import MetadataTypesSettingsEntity from "../metadata/metadataTypesSettingsEntity";
import {
  RESOURCE_TYPE_PASSWORD_AND_DESCRIPTION_SLUG,
  RESOURCE_TYPE_PASSWORD_DESCRIPTION_TOTP_SLUG,
  RESOURCE_TYPE_PASSWORD_STRING_SLUG,
  RESOURCE_TYPE_TOTP_SLUG,
  RESOURCE_TYPE_V5_CUSTOM_FIELDS_SLUG,
  RESOURCE_TYPE_V5_DEFAULT_SLUG,
  RESOURCE_TYPE_V5_DEFAULT_TOTP_SLUG,
  RESOURCE_TYPE_V5_PASSWORD_STRING_SLUG,
  RESOURCE_TYPE_V5_STANDALONE_NOTE_SLUG,
  RESOURCE_TYPE_V5_STANDALONE_PIN_CODE_SLUG,
  RESOURCE_TYPE_V5_TOTP_SLUG,
} from "../resourceType/resourceTypeSchemasDefinition";
import ResourceTypesCollection from "../resourceType/resourceTypesCollection";

const partialCheckboxesMapping = {
  passwordV4: [RESOURCE_TYPE_PASSWORD_STRING_SLUG, RESOURCE_TYPE_PASSWORD_AND_DESCRIPTION_SLUG],
  totpV4: [RESOURCE_TYPE_TOTP_SLUG],
  passwordV5: [RESOURCE_TYPE_V5_DEFAULT_SLUG, RESOURCE_TYPE_V5_PASSWORD_STRING_SLUG],
  totpV5: [RESOURCE_TYPE_V5_TOTP_SLUG],
  customFieldsV5: [RESOURCE_TYPE_V5_CUSTOM_FIELDS_SLUG],
  noteV5: [RESOURCE_TYPE_V5_STANDALONE_NOTE_SLUG],
  pinCodeV5: [RESOURCE_TYPE_V5_STANDALONE_PIN_CODE_SLUG],
};

const fullResourceTypesMapping = {
  passwordV4: [
    RESOURCE_TYPE_PASSWORD_STRING_SLUG,
    RESOURCE_TYPE_PASSWORD_AND_DESCRIPTION_SLUG,
    RESOURCE_TYPE_PASSWORD_DESCRIPTION_TOTP_SLUG,
  ],
  totpV4: [RESOURCE_TYPE_TOTP_SLUG, RESOURCE_TYPE_PASSWORD_DESCRIPTION_TOTP_SLUG],
  passwordV5: [
    RESOURCE_TYPE_V5_DEFAULT_SLUG,
    RESOURCE_TYPE_V5_PASSWORD_STRING_SLUG,
    RESOURCE_TYPE_V5_DEFAULT_TOTP_SLUG,
  ],
  totpV5: [RESOURCE_TYPE_V5_TOTP_SLUG, RESOURCE_TYPE_V5_DEFAULT_TOTP_SLUG],
  customFieldsV5: [RESOURCE_TYPE_V5_CUSTOM_FIELDS_SLUG],
  noteV5: [RESOURCE_TYPE_V5_STANDALONE_NOTE_SLUG],
  pinCodeV5: [RESOURCE_TYPE_V5_STANDALONE_PIN_CODE_SLUG],
};

class ResourceTypesFormEntity extends EntityV2 {
  /**
   * @constructor
   * @param {object} resourceTypeFormDto
   */
  constructor(resourceTypeFormDto, options) {
    super(resourceTypeFormDto, options);

    if (this._props.resource_types) {
      this._resource_types = new ResourceTypesCollection(this._props.resource_types);
    }
  }

  /**
   * Get resource type form entity schema
   * @returns {Object} schema
   */
  static getSchema() {
    return {
      type: "object",
      required: [
        "password_v4",
        "password_v5",
        "totp_v4",
        "totp_v5",
        "custom_fields_v5",
        "note_v5",
        "pin_code_v5",
        "password_v4_count",
        "password_v5_count",
        "totp_v4_count",
        "totp_v5_count",
        "custom_fields_v5_count",
        "note_v5_count",
        "pin_code_v5_count",
        "resource_types",
        "has_v4_resource_types",
        "has_v5_resource_types",
      ],
      properties: {
        password_v4: {
          type: "boolean",
        },
        password_v5: {
          type: "boolean",
        },
        totp_v4: {
          type: "boolean",
        },
        totp_v5: {
          type: "boolean",
        },
        custom_fields_v5: {
          type: "boolean",
        },
        note_v5: {
          type: "boolean",
        },
        pin_code_v5: {
          type: "boolean",
        },
        password_v4_count: {
          type: "integer",
        },
        password_v5_count: {
          type: "integer",
        },
        totp_v4_count: {
          type: "integer",
        },
        totp_v5_count: {
          type: "integer",
        },
        custom_fields_v5_count: {
          type: "integer",
        },
        note_v5_count: {
          type: "integer",
        },
        pin_code_v5_count: {
          type: "integer",
        },
        has_v4_resource_types: {
          type: "boolean",
        },
        has_v5_resource_types: {
          type: "boolean",
        },
        resource_types: ResourceTypesCollection.getSchema(), // all resource types collection (available and deleted)
      },
    };
  }

  /**
   * Creates a resource type form entity based on the given resource types collection
   * @param {ResourceTypesCollection} resource_types
   * @returns {ResourceTypesFormEntity}
   */
  static createFormResourcesTypesCollection(resource_types) {
    if (!(resource_types instanceof ResourceTypesCollection)) {
      throw new TypeError("The parameter 'resource_types' is not a valid 'ResourceTypesCollection' type.");
    }

    const availableResourceTypesDto = resource_types.items.filter((rt) => !rt.isDeleted());
    const availableResourceTypes = new ResourceTypesCollection(availableResourceTypesDto);

    const password_v4 = this._areAllResourceTypesAvailable(partialCheckboxesMapping.passwordV4, availableResourceTypes);
    const password_v5 = this._areAllResourceTypesAvailable(partialCheckboxesMapping.passwordV5, availableResourceTypes);
    const totp_v4 = this._areAllResourceTypesAvailable(partialCheckboxesMapping.totpV4, availableResourceTypes);
    const totp_v5 = this._areAllResourceTypesAvailable(partialCheckboxesMapping.totpV5, availableResourceTypes);
    const custom_fields_v5 = this._areAllResourceTypesAvailable(
      partialCheckboxesMapping.customFieldsV5,
      availableResourceTypes,
    );
    const note_v5 = this._areAllResourceTypesAvailable(partialCheckboxesMapping.noteV5, availableResourceTypes);
    const pin_code_v5 = this._areAllResourceTypesAvailable(partialCheckboxesMapping.pinCodeV5, availableResourceTypes);

    const password_v4_count = this._getResourcesCountForResourceTypeFamily(
      fullResourceTypesMapping.passwordV4,
      resource_types,
    );
    const password_v5_count = this._getResourcesCountForResourceTypeFamily(
      fullResourceTypesMapping.passwordV5,
      resource_types,
    );
    const totp_v4_count = this._getResourcesCountForResourceTypeFamily(fullResourceTypesMapping.totpV4, resource_types);
    const totp_v5_count = this._getResourcesCountForResourceTypeFamily(fullResourceTypesMapping.totpV5, resource_types);
    const custom_fields_v5_count = this._getResourcesCountForResourceTypeFamily(
      fullResourceTypesMapping.customFieldsV5,
      availableResourceTypes,
    );
    const note_v5_count = this._getResourcesCountForResourceTypeFamily(fullResourceTypesMapping.noteV5, resource_types);
    const pin_code_v5_count = this._getResourcesCountForResourceTypeFamily(
      fullResourceTypesMapping.pinCodeV5,
      resource_types,
    );

    const has_v4_resource_types = resource_types.hasSomeOfVersion("v4");
    const has_v5_resource_types = resource_types.hasSomeOfVersion("v5");

    return new ResourceTypesFormEntity({
      password_v4,
      password_v5,
      totp_v4,
      totp_v5,
      custom_fields_v5,
      note_v5,
      pin_code_v5,
      password_v4_count,
      password_v5_count,
      totp_v4_count,
      totp_v5_count,
      note_v5_count,
      pin_code_v5_count,
      custom_fields_v5_count,
      has_v4_resource_types,
      has_v5_resource_types,
      resource_types,
    });
  }

  /**
   * Returns the sum of the quantity of resource for all the given resource types.
   * @param {Array<string>} requiredResourceSlugs
   * @param {ResourceTypesCollection} resourceTypesCollection
   * @returns {integer}
   * @private
   */
  static _getResourcesCountForResourceTypeFamily(requiredResourceSlugs, resourceTypesCollection) {
    let count = 0;
    for (let i = 0; i < requiredResourceSlugs.length; i++) {
      count += resourceTypesCollection.getFirstBySlug(requiredResourceSlugs[i])?.resourcesCount || 0;
    }
    return count;
  }

  /**
   * Returns true if all the required resource types are part of the available resource types collection
   * @param {Array<string>} requiredResourceTypes
   * @param {ResourceTypesCollection} availableResourceTypesCollection
   * @returns {boolean}
   * @private
   */
  static _areAllResourceTypesAvailable(requiredResourceTypes, availableResourceTypesCollection) {
    return requiredResourceTypes.every((slug) => availableResourceTypesCollection.hasOneWithSlug(slug));
  }

  /**
   * @inheritDoc
   * @throws {EntityValidationError} If a resource type family is deleted but has resource associated.
   * @throws {EntityValidationError} If all the resource type are disabled.
   */
  validateBuildRules() {
    let error = null;
    if (!this._props.password_v4 && this._props.password_v4_count > 0) {
      error = error || new EntityValidationError();
      error.addError(
        "password_v4",
        "has_content",
        "Password content type is disabled but there are existing password resources.",
      );
    }
    if (!this._props.totp_v4 && this._props.totp_v4_count > 0) {
      error = error || new EntityValidationError();
      error.addError("totp_v4", "has_content", "TOTP content type is disabled but there are existing TOTP resources.");
    }
    if (!this._props.password_v5 && this._props.password_v5_count > 0) {
      error = error || new EntityValidationError();
      error.addError(
        "password_v5",
        "has_content",
        "Password content type is disabled but there are existing password resources.",
      );
    }
    if (!this._props.totp_v5 && this._props.totp_v5_count > 0) {
      error = error || new EntityValidationError();
      error.addError("totp_v5", "has_content", "TOTP content type is disabled but there are existing TOTP resources.");
    }
    if (!this._props.custom_fields_v5 && this._props.custom_fields_v5_count > 0) {
      error = error || new EntityValidationError();
      error.addError(
        "custom_fields_v5",
        "has_content",
        "Custom fields content type is disabled but there are existing custom fields resources.",
      );
    }
    if (!this._props.note_v5 && this._props.note_v5_count > 0) {
      error = error || new EntityValidationError();
      error.addError("note_v5", "has_content", "Note content type is disabled but there are existing note resources.");
    }
    if (!this._props.pin_code_v5 && this._props.pin_code_v5_count > 0) {
      error = error || new EntityValidationError();
      error.addError(
        "pin_code_v5",
        "has_content",
        "Pin code content type is disabled but there are existing pin code resources.",
      );
    }
    if (
      !this._props.password_v4 &&
      !this._props.totp_v4 &&
      !this._props.password_v5 &&
      !this._props.totp_v5 &&
      !this._props.note_v5 &&
      !this._props.pin_code_v5
    ) {
      const message = "At least one content type should be allowed";
      const rule = "minimum_requirement";

      error = error || new EntityValidationError();
      error.addError("password_v4", rule, message);
      error.addError("totp_v4", rule, message);
      error.addError("password_v5", rule, message);
      error.addError("totp_v5", rule, message);
      error.addError("custom_fields_v5", rule, message);
      error.addError("note_v5", rule, message);
      error.addError("pin_code_v5", rule, message);
    }

    if (error) {
      throw error;
    }
  }

  /**
   * Runs a health check for the form
   * @param {MetadataTypesSettingsEntity} metadataTypesSettings
   * @param {MetadataKeysCollection} metadataKeysCollection
   * @returns {EntityValidationError|null}
   */
  verifyHealth(metadataTypesSettings, metadataKeysCollection) {
    if (typeof metadataTypesSettings === "undefined") {
      return null;
    }
    if (typeof metadataKeysCollection === "undefined") {
      return null;
    }

    if (!(metadataTypesSettings instanceof MetadataTypesSettingsEntity)) {
      throw new TypeError("The parameter 'metadataTypesSettings' is not a valid 'MetadataTypesSettingsEntity' type.");
    }
    if (!(metadataKeysCollection instanceof MetadataKeysCollection)) {
      throw new TypeError("The parameter 'metadataKeysCollection' is not a valid 'MetadataKeysCollection' type.");
    }

    let result = null;
    if (metadataTypesSettings.allowCreationOfV4Resources && !this._props.password_v4 && !this._props.totp_v4) {
      result = new EntityValidationError();
      result.addError(
        "password_v4",
        "is_creation_alowed",
        "V4 resource creation is enabled but password content type is disabled.",
      );
      result.addError(
        "totp_v4",
        "is_creation_alowed",
        "V4 resource creation is enabled but TOTP content type is disabled.",
      );
    }

    if (!metadataTypesSettings.allowCreationOfV4Resources && this._props.password_v4) {
      result = result || new EntityValidationError();
      result.addError("password_v4", "is_creation_not_alowed", "Creation of resource type v4 is not allowed.");
    }

    if (!metadataTypesSettings.allowCreationOfV4Resources && this._props.totp_v4) {
      result = result || new EntityValidationError();
      result.addError("totp_v4", "is_creation_not_alowed", "Creation of resource type v4 is not allowed.");
    }

    if (
      metadataTypesSettings.allowCreationOfV5Resources &&
      !this._props.password_v5 &&
      !this._props.totp_v5 &&
      !this._props.custom_fields_v5 &&
      !this._props.note_v5 &&
      !this._props.pin_code_v5
    ) {
      result = result || new EntityValidationError();
      result.addError(
        "password_v5",
        "is_creation_alowed",
        "V5 resource creation is enabled but password content type is disabled.",
      );
      result.addError(
        "totp_v5",
        "is_creation_alowed",
        "V5 resource creation is enabled but TOTP content type is disabled.",
      );
      result.addError(
        "custom_fields_v5",
        "is_creation_alowed",
        "V5 resource creation is enabled but custom fields content type is disabled.",
      );
      result.addError(
        "note_v5",
        "is_creation_alowed",
        "V5 resource creation is enabled but note content type is disabled.",
      );
      result.addError(
        "pin_code_v5",
        "is_creation_alowed",
        "V5 resource creation is enabled but pin code content type is disabled.",
      );
    }

    if (!metadataTypesSettings.allowCreationOfV5Resources && this._props.password_v5) {
      result = result || new EntityValidationError();
      result.addError("password_v5", "is_creation_not_alowed", "Creation of resource type v5 is not allowed.");
    }

    if (!metadataTypesSettings.allowCreationOfV5Resources && this._props.totp_v5) {
      result = result || new EntityValidationError();
      result.addError("totp_v5", "is_creation_not_alowed", "Creation of resource type v5 is not allowed.");
    }

    if (!metadataTypesSettings.allowCreationOfV5Resources && this._props.note_v5) {
      result = result || new EntityValidationError();
      result.addError("note_v5", "is_creation_not_alowed", "Creation of resource type v5 is not allowed.");
    }

    if (!metadataTypesSettings.allowCreationOfV5Resources && this._props.custom_fields_v5) {
      result = result || new EntityValidationError();
      result.addError("custom_fields_v5", "is_creation_not_alowed", "Creation of resource type v5 is not allowed.");
    }

    if (!metadataTypesSettings.allowCreationOfV5Resources && this._props.pin_code_v5) {
      result = result || new EntityValidationError();
      result.addError("pin_code_v5", "is_creation_not_alowed", "Creation of resource type v5 is not allowed.");
    }

    const activeMetadataKeysCollection = metadataKeysCollection.items.filter((metadataKey) => !metadataKey.expired);
    if (activeMetadataKeysCollection.length === 0 && this._props.password_v5) {
      result = result || new EntityValidationError();
      result.addError("password_v5", "active_metadata_key", "No active metadata key defined.");
    }

    if (activeMetadataKeysCollection.length === 0 && this._props.totp_v5) {
      result = result || new EntityValidationError();
      result.addError("totp_v5", "active_metadata_key", "No active metadata key defined.");
    }

    if (activeMetadataKeysCollection.length === 0 && this._props.custom_fields_v5) {
      result = result || new EntityValidationError();
      result.addError("custom_fields_v5", "active_metadata_key", "No active metadata key defined.");
    }

    if (activeMetadataKeysCollection.length === 0 && this._props.note_v5) {
      result = result || new EntityValidationError();
      result.addError("note_v5", "active_metadata_key", "No active metadata key defined.");
    }

    if (activeMetadataKeysCollection.length === 0 && this._props.pin_code_v5) {
      result = result || new EntityValidationError();
      result.addError("pin_code_v5", "active_metadata_key", "No active metadata key defined.");
    }

    return result;
  }

  /**
   * Get the DTO of properties managed by the form.
   * @returns {object}
   */
  toFormDto() {
    return {
      password_v4: this._props.password_v4,
      password_v5: this._props.password_v5,
      totp_v4: this._props.totp_v4,
      totp_v5: this._props.totp_v5,
      custom_fields_v5: this._props.custom_fields_v5,
      note_v5: this._props.note_v5,
      pin_code_v5: this._props.pin_code_v5,
      password_v4_count: this._props.password_v4_count,
      password_v5_count: this._props.password_v5_count,
      totp_v4_count: this._props.totp_v4_count,
      totp_v5_count: this._props.totp_v5_count,
      custom_fields_v5_count: this._props.custom_fields_v5_count,
      note_v5_count: this._props.note_v5_count,
      pin_code_v5_count: this._props.pin_code_v5_count,
      has_v4_resource_types: this._props.has_v4_resource_types,
      has_v5_resource_types: this._props.has_v5_resource_types,
      resource_types: this._resource_types,
    };
  }

  /**
   * Get the resource types collection DTO based on the properties of the form.
   * @returns {ResourceTypesCollection}
   */
  toResourceTypesCollection() {
    //computes the new resource types collection state based on the form
    const availableResourceTypes = this._resource_types.items.filter(
      (rt) =>
        (this._props.password_v4 && rt.isV4() && rt.hasPassword() && !rt.hasTotp()) || // password v4 only resource types
        (this._props.totp_v4 && rt.isV4() && !rt.hasPassword() && rt.hasTotp()) || // standalone totp v4 resource types
        (this._props.totp_v4 && this._props.password_v4 && rt.isV4() && rt.hasPassword() && rt.hasTotp()) || // password + totp v4 resource types
        (this._props.password_v5 && rt.isV5() && rt.hasPassword() && !rt.hasTotp()) || // password v5 only resource types
        (this._props.totp_v5 && rt.isV5() && !rt.hasPassword() && rt.hasTotp()) || // standalone v5 only resource types
        (this._props.totp_v5 && this._props.password_v5 && rt.isV5() && rt.hasPassword() && rt.hasTotp()) || // password + totp v5 resource types
        (this._props.custom_fields_v5 && rt.slug === RESOURCE_TYPE_V5_CUSTOM_FIELDS_SLUG) || // note v5 only resource types
        (this._props.note_v5 && rt.slug === RESOURCE_TYPE_V5_STANDALONE_NOTE_SLUG) || // note v5 only resource types
        (this._props.pin_code_v5 && rt.slug === RESOURCE_TYPE_V5_STANDALONE_PIN_CODE_SLUG), // pin code v5 only resource types
    );
    const deletedResourceTypes = this._resource_types.items.filter(
      (rt) => !availableResourceTypes.some((art) => rt.id === art.id),
    );

    //keep only the diff changes
    const resourceTypesToEnable = availableResourceTypes.filter((art) => art.isDeleted());
    const resourceTypesToDelete = deletedResourceTypes.filter((drt) => !drt.isDeleted());

    //mark resource types as deleted
    const now = DateTime.now().toISO();
    for (let i = 0; i < resourceTypesToDelete.length; i++) {
      resourceTypesToDelete[i].deleted = now;
    }

    //mark resource types as undeleted
    for (let i = 0; i < resourceTypesToEnable.length; i++) {
      resourceTypesToEnable[i].deleted = null;
    }

    return new ResourceTypesCollection([...resourceTypesToEnable, ...resourceTypesToDelete]);
  }
}

export default ResourceTypesFormEntity;
